207	    public ClientAgingResponse agingForClient(Long clientId) {
208	        Client client = clients.findById(clientId)
209	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
210	        LocalDate today = LocalDate.now(clock);
211	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
212	        Map<Long, BigDecimal> paid = paidByInvoice(found);
213	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
214	        Function<String, MoneyRule> rules = moneyRules();
215	        BigDecimal current = BigDecimal.ZERO.setScale(2);
216	        BigDecimal days30To60 = BigDecimal.ZERO.setScale(2);
217	        BigDecimal days60Plus = BigDecimal.ZERO.setScale(2);
218	        for (Invoice invoice : found) {
219	            BigDecimal invoicePaid = paid.getOrDefault(invoice.getId(), BigDecimal.ZERO);
220	            BigDecimal invoiceCredited = credited.getOrDefault(invoice.getId(), BigDecimal.ZERO);
221	            InvoiceStatus status = invoice.statusFor(invoicePaid, invoiceCredited);
222	            if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
223	                continue;
224	            }
225	            BigDecimal due = rules.apply(invoice.getCurrency()).round(invoice.amountDue(invoicePaid, invoiceCredited));
226	            if (due.signum() <= 0) {
227	                continue;
228	            }
229	            long overdue = invoice.getDueDate() == null ? 0
230	                    : ChronoUnit.DAYS.between(invoice.getDueDate(), today);
231	            if (overdue > 60) {
232	                days60Plus = days60Plus.add(due);
233	            } else if (overdue > 30) {
234	                days30To60 = days30To60.add(due);
235	            } else {
236	                current = current.add(due);
237	            }
238	        }
239	        return new ClientAgingResponse(client.getId(), client.getCurrency(), today,
240	                current.setScale(2, RoundingMode.HALF_UP), days30To60.setScale(2, RoundingMode.HALF_UP),
241	                days60Plus.setScale(2, RoundingMode.HALF_UP));
242	    }
