244	    /**
245	     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
246	     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
247	     * when it was paid in. Each amount is rounded by the rule of the currency it is in, as the invoice is, so the
248	     * balances add up to the cent.
249	     */
250	    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found, Function<String, MoneyRule> rules) {
251	        MoneyRule clientRule = clients.findById(clientId).map(c -> rules.apply(c.getCurrency())).orElse(MoneyRule.CENTS);
252	        Map<Long, MoneyRule> invoiceRules = new HashMap<>();
253	        found.forEach(i -> invoiceRules.put(i.getId(), rules.apply(i.getCurrency())));
254	        List<StatementEntry> entries = new ArrayList<>();
255	        List<Long> sent = new ArrayList<>();
256	        Map<Long, String> poNumbers = new HashMap<>();
257	        for (Invoice invoice : found) {
258	            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
259	                continue;
260	            }
261	            sent.add(invoice.getId());
262	            if (invoice.getPoNumber() != null) {
263	                poNumbers.put(invoice.getId(), invoice.getPoNumber());
264	            }
265	            if (invoice.getStatus() != InvoiceStatus.VOID) {
266	                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
267	                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoiceRules.get(invoice.getId()).round(invoice.getAmount()),
268	                        invoice.getPoNumber()));
269	            }
270	        }
271	        if (!sent.isEmpty()) {
272	            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
273	                if (payment.getDepositApplicationId() == null) {
274	                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
275	                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(),
276	                            invoiceRules.get(payment.getInvoiceId()).round(payment.getAmount()),
277	                            poNumbers.get(payment.getInvoiceId())));
278	                }
279	            }
280	            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
281	                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
282	                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
283	                        "Credit note on invoice #" + note.getInvoiceId(),
284	                        invoiceRules.get(note.getInvoiceId()).round(note.getAmount()),
285	                        poNumbers.get(note.getInvoiceId())));
286	            }
287	        }
288	        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
289	            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
290	                    "Deposit", clientRule.round(deposit.getAmount()), null));
291	        }
292	        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
293	            entries.add(StatementEntry.charge(StatementEntry.Kind.REFUND, refund.getId(), null, refund.getDate(),
294	                    "Refund", clientRule.round(refund.getAmount()), null));
295	        }
296	        return entries;
297	    }
